import re,hashlib,json
from current_localization_contracts import fixture
NAME='jeju_ainu_manchu_priority_wording.json'
TAGS=frozenset({'jje','ain-Kana','mnc-Mong'})
# Bind this compact immutable reviewed fixture, never a whole-source snapshot.
FIXTURE_SHA256='7cad5e1c6ca50027cd6ce94cf44b9f81c8bf3ff074bba1e43228918391c47b3a'
def require_fixture_binding(data):
    actual=hashlib.sha256(json.dumps(data,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
    if actual!=FIXTURE_SHA256:raise ValueError('Complete reviewed fixture binding differs')
    return data

MEMORY_ADDITIONS=frozenset()
TAGGED_ADDITIONS=frozenset()
SVG_ADDITIONS=frozenset()
def current_row(tag,key):
    if tag not in TAGS:raise ValueError('Outside finite JJE/AIN/MNC set')
    data=require_fixture_binding(fixture(NAME));locale=data['locales'][tag]
    if key not in locale['accepted']:raise ValueError('No accepted current value')
    source=data['sources'][key];previous=locale['predecessors'].get(key)
    return {'source':source['source'],'source_attributes':source['attributes'],'target':locale['accepted'][key],
            'attributes':locale['target_attribute_exceptions'].get(key,{'name':key}),
            'previous_target':previous['target'] if previous else None,
            'previous_attributes':previous['attributes'] if previous else None,
            'type':source['type'],'changed':key in locale['changed']}
def _display(value):
    if value.startswith('"') and value.endswith('"'):value=value[1:-1]
    return re.sub(r'\\(u[0-9a-fA-F]{4}|.)',lambda m:chr(int(m[1][1:],16)) if m[1].startswith('u') else {'n':'\n','t':'\t','r':'\r'}.get(m[1],m[1]),value)
def display(tag,key):
    value=current_row(tag,key)['target']
    if isinstance(value,dict):return {q:_display(v)for q,v in value.items()}
    if value.startswith('@string/'):
        if key!='ui_save_a5d0d9' or value!='@string/ui_save':raise ValueError('Unreviewed alias')
        return _display(current_row(tag,'ui_save')['target'])
    return _display(value)


def current_jeju_sampled_modality_value(tag, historical):
    if tag!='jje':return historical
    key='ui_sampled_resize_memory_explanation'
    row=current_row(tag,key)
    if row['previous_target']!=historical or row['previous_attributes']!={'name':key}:
        raise ValueError('Exact historical Jeju complete warning differs')
    if row['source']!='Estimates include the current canvas and clipboard, sampled decoding and editing buffers. Actual memory use varies. A smaller copy loses detail. The original file stays unchanged.':raise ValueError('Historical English differs')
    return row['target']


# Two existing, formerly held targets now have separate complete-value review.
# This is not an addition or a mutation of the original paired-successor inventory.
MEMORY_CORRECTIONS=frozenset({
    ('jje','ui_no_resize_fits_decoder_memory'),
    ('jje','ui_assembly_source_memory_floor'),
})
def current_jeju_memory_value(tag,key,historical_value,english):
    if (tag,key) not in MEMORY_CORRECTIONS:
        raise ValueError('Outside exact Jeju memory correction pair')
    row=current_row(tag,key)
    if (row['type']!='string' or not row['changed'] or row['previous_target'] is None or
        row['previous_target']!=historical_value or row['previous_attributes']!={'name':key}):
        raise ValueError('Exact historical Jeju memory predecessor differs')
    if row['source']!=english or row['source_attributes']!={'name':key} or row['attributes']!={'name':key}:
        raise ValueError('Exact Jeju memory source or attributes differ')
    return row['target']

